-- Generated init SQL for Renewal Screening Workbench

CREATE TABLE IF NOT EXISTS policies (
  id TEXT PRIMARY KEY,
  country TEXT,
  customerName TEXT,
  customerIdentifier TEXT,
  brokerName TEXT,
  renewalDate TEXT,
  currency TEXT,
  premium REAL,
  openClaim INTEGER,
  premiumUnpaid INTEGER,
  renewalTypeManual INTEGER,
  systemListedCompany INTEGER,
  isFrame INTEGER,
  dnbNoMatch INTEGER,
  dnbStatusInactive INTEGER,
  dnbRatingBelowA INTEGER,
  latestProfitNegative INTEGER,
  assetsMovedSignificant INTEGER,
  dnbListedCompany INTEGER,
  consolidatedAccounts INTEGER,
  latestConsolidatedProfitNegative INTEGER,
  consolidatedAssetsMovedSignificant INTEGER,
  businessLine TEXT,
  stage1FlagCount INTEGER,
  stage2FlagCount INTEGER,
  routing TEXT,
  attention TEXT,
  flagReasons TEXT,
  dnbRating TEXT,
  failureScorePercentile INTEGER,
  latestNetIncome INTEGER,
  assetsChangePercent INTEGER,
  dnbOperatingStatusLabel TEXT,
  dnbListedExchange TEXT
);

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  name TEXT,
  country TEXT
);

CREATE TABLE IF NOT EXISTS review_states (
  policyId TEXT PRIMARY KEY,
  status TEXT,
  assignedUserId TEXT
);

CREATE TABLE IF NOT EXISTS comments (
  id TEXT PRIMARY KEY,
  policyId TEXT,
  userId TEXT,
  text TEXT,
  createdAt TEXT
);

CREATE TABLE IF NOT EXISTS activity_log (
  id TEXT PRIMARY KEY,
  policyId TEXT,
  eventType TEXT,
  userId TEXT,
  detail TEXT,
  createdAt TEXT
);

